<div class="border-top py-3" style="margin-left:{{ $depth*1.25 }}rem"><form method="post" action="{{ route('admin.menus.items.update',[$menu,$item]) }}" class="row g-2 align-items-end"><input type="hidden" name="_form" value="menu-item-{{ $item->id }}">@php($rowOld = old('_form') === 'menu-item-'.$item->id)@csrf @method('PUT')<div class="col-md-3"><label class="form-label small">{{ $depth ? 'Dropdown item' : 'Menu item' }} label</label><input class="form-control" name="label" value="{{ $rowOld ? old('label') : $item->label }}" required maxlength="120"></div><div class="col-md-4"><label class="form-label small">URL</label><input class="form-control" name="url" value="{{ $rowOld ? old('url') : $item->url }}" required maxlength="255"></div><div class="col-md-2"><label class="form-label small">Target</label><select class="form-select" name="target"><option value="_self" @selected(($rowOld ? old('target') : $item->target)==='_self')>Same tab</option><option value="_blank" @selected(($rowOld ? old('target') : $item->target)==='_blank')>New tab</option></select></div><div class="col-md-1"><label class="form-label small">Order</label><input class="form-control" type="number" name="sort_order" value="{{ $rowOld ? old('sort_order') : $item->sort_order }}" min="0" max="9999"></div><div class="col-md-1"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_visible" value="1" @checked($rowOld ? old('is_visible') : $item->is_visible)><label class="form-check-label small">Show</label></div></div><div class="col-md-1"><button class="btn btn-sm btn-outline-success w-100">Save</button></div></form>@if(!empty(($hiddenLinks ?? [])[$item->id] ?? null))<div class="alert alert-warning small py-1 px-2 mt-2 mb-0" role="status" data-hidden-link="{{ $item->id }}"><strong>Hidden on the website:</strong> {{ $hiddenLinks[$item->id] }}</div>@endif<div class="d-flex flex-wrap justify-content-end align-items-center gap-1 mt-2"><form method="post" action="{{ route('admin.menus.items.move',[$menu,$item,'up']) }}">@csrf<button class="btn btn-sm btn-outline-secondary" aria-label="Move {{ $item->label }} up" @disabled($isFirst ?? false)>↑</button></form><form method="post" action="{{ route('admin.menus.items.move',[$menu,$item,'down']) }}">@csrf<button class="btn btn-sm btn-outline-secondary" aria-label="Move {{ $item->label }} down" @disabled($isLast ?? false)>↓</button></form>@if($item->children->isNotEmpty())<span class="small text-secondary ms-2" data-remove-blocked="{{ $item->id }}">To remove this item, first remove its {{ $item->children->count() }} dropdown {{ Str::plural('item', $item->children->count()) }}.</span>@else<form method="post" action="{{ route('admin.menus.items.destroy',[$menu,$item]) }}">@csrf @method('DELETE')<button class="btn btn-sm btn-link text-danger" data-confirm="Remove “{{ $item->label }}” from {{ $menu->name }}? This cannot be undone.">Remove</button></form>@endif</div></div>
